from pathlib import Path
import re
p=Path('index.html'); s=p.read_text(encoding='utf-8'); old=s
scripts=re.findall(r'<script\b[^>]*>.*?</script>',old,re.S|re.I)
ids=set(re.findall(r'\bid=["\']([^"\']+)["\']',old,re.I)); classes=set()
for x in re.findall(r'\bclass=["\']([^"\']*)["\']',old,re.I): classes.update(x.split())
