hero='''\n<nav class="sticky top-0 z-[11000] border-b border-white/10 bg-slate-950/80 backdrop-blur-xl dark:bg-slate-950/80"><div class="mx-auto flex max-w-7xl items-center justify-between gap-3 px-4 py-3"><a href="index.html" class="flex items-center gap-2 font-black text-slate-900 no-underline dark:text-white"><img src="images/meshwar-logo.png" class="h-11 w-11 rounded-xl border border-white/10 bg-white/5 p-1" alt="MeshWar"><span>MeshWar</span></a><div class="flex items-center gap-2"><a href="#localStoresPublic" class="rounded-full border border-white/10 px-3 py-2 text-xs font-bold text-slate-700 no-underline dark:text-slate-200">🏪 المتاجر</a><button id="meshwarThemeToggle" type="button" class="rounded-full border border-white/10 bg-white/5 px-3 py-2 text-slate-700 dark:text-slate-100">☾</button></div></div></nav>\n<section class="mx-auto max-w-7xl px-4 pt-8"><div class="grid gap-6 overflow-hidden rounded-3xl border border-slate-200 bg-white/70 p-6 shadow-2xl backdrop-blur-md md:grid-cols-[1.15fr_.85fr] md:p-10 dark:border-white/10 dark:bg-slate-900/60"><div><span class="inline-flex rounded-full border border-sky-400/20 bg-sky-400/10 px-3 py-1 text-xs font-black text-sky-500">MeshWar • Smart Commerce</span><h2 class="mt-4 text-4xl font-black leading-tight text-slate-950 md:text-6xl dark:text-white">تسوّق، اطلب، وتابع<br><span class="bg-gradient-to-r from-sky-400 to-indigo-500 bg-clip-text text-transparent">من مكان واحد.</span></h2><p class="mt-4 max-w-2xl text-sm leading-7 text-slate-500 dark:text-slate-400">واجهة موحدة للمتاجر المحلية والعالمية مع وصول سريع للطلب والتتبع.</p><div class="mt-6 flex flex-wrap gap-3"><button type="button" onclick="document.getElementById('orderModal').style.display='block'" class="rounded-xl bg-gradient-to-r from-sky-600 to-indigo-600 px-5 py-3 font-black text-white shadow-lg transition-all duration-300 hover:scale-[1.02] hover:shadow-cyan-500/20">طلب منتج مباشر</button><a href="#localStoresPublic" class="rounded-xl border border-slate-200 bg-white/50 px-5 py-3 font-black text-slate-700 no-underline dark:border-white/10 dark:bg-white/5 dark:text-slate-200">المتاجر المحلية</a></div></div><div class="rounded-2xl border border-slate-200 bg-slate-50/70 p-5 dark:border-white/10 dark:bg-slate-950/50"><div class="text-sm font-black">تتبع سريع للطلب</div><div class="mt-1 text-xs text-slate-500 dark:text-slate-400">أدخل رقم الطلب أو الباركود.</div><div class="mt-4 flex gap-2"><input id="meshwarHeroTrackInput" class="min-w-0 flex-1 rounded-xl border border-slate-200 bg-white px-3 py-3 outline-none focus:border-sky-400 dark:border-white/10 dark:bg-slate-900" placeholder="MW / رقم الطلب / الباركود"><button id="meshwarHeroTrackBtn" type="button" onclick="meshwarQuickTrack()" class="rounded-xl bg-sky-600 px-4 font-black text-white">تتبع</button></div></div></div></section>\n'''
if 'meshwarHeroTrackInput' not in s: s=s.replace('<body>', '<body>\n'+hero,1)
extra='''\n<script>/* MESHWAR_INDEX_UI_V3 */(function(){const r=document.documentElement,b=document.getElementById('meshwarThemeToggle');if(b)b.onclick=()=>{const d=!r.classList.contains('dark');r.classList.toggle('dark',d);try{localStorage.setItem('meshwar-theme',d?'dark':'light')}catch{};b.textContent=d?'☀':'☾'}})();function meshwarQuickTrack(){const a=document.getElementById('meshwarHeroTrackInput'),v=String(a?.value||'').trim();if(!v)return a?.focus();const x=[...document.querySelectorAll('input')].find(e=>e!==a&&/track|order|barcode|shipment|code|تتبع|طلب|باركود|شحنة/i.test([e.id,e.name,e.placeholder].filter(Boolean).join(' ')));if(x){x.value=v;x.dispatchEvent(new Event('input',{bubbles:true}));}if(typeof window.trackOrder==='function')return window.trackOrder();if(typeof window.trackShipment==='function')return window.trackShipment();const b=[...document.querySelectorAll('button,a')].find(e=>e.id!=='meshwarHeroTrackBtn'&&/تتبع|track/i.test(e.textContent||''));if(b){b.scrollIntoView({behavior:'smooth',block:'center'});if(b.tagName==='BUTTON')setTimeout(()=>b.click(),300)}}<\/script>\n'''
if 'MESHWAR_INDEX_UI_V3' not in s: s=s.replace('</body>',extra+'</body>',1)
for i,b in enumerate(scripts):
    if b not in s: raise SystemExit(f'legacy script changed: {i}')
new_ids=set(re.findall(r'\bid=["\']([^"\']+)["\']',s,re.I)); new_classes=set()
for x in re.findall(r'\bclass=["\']([^"\']*)["\']',s,re.I): new_classes.update(x.split())
if ids-new_ids: raise SystemExit('legacy id removed')
if classes-new_classes: raise SystemExit('legacy class removed')
for t in ('orderModal','localStoresPublic','localSpecialtyFilters','localStoresPublicGrid','fixed-order-btn'):
    if t not in s: raise SystemExit('critical token missing: '+t)
p.write_text(s,encoding='utf-8')
